import{_ as r,l as o,o as e,c as n,v as t,p as s,x as i,d as E,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const V=JSON.parse('{"title":"EUV 照明设置","description":"","frontmatter":{"title":"EUV 照明设置","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/euv-illumination-settings.md","filePath":"litho/euv-illumination-settings.md","lastUpdated":1789023840000}'),h={name:"litho/euv-illumination-settings.md"};function u(c,a,A,S,m,_){const l=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="euv-照明设置" tabindex="-1">EUV 照明设置 <a class="header-anchor" href="#euv-照明设置" aria-label="Permalink to &quot;EUV 照明设置&quot;">​</a></h1><div class="epigraph"><p>光瞳可以切成环、极子或自由形状。EUV 的约束是光子、多层角谱和掩模三维，不能把浸没 SMO 的 σ 表直接粘过来。</p><footer>—— 对照 ASML FlexPupil / EUV SMO 公开叙述；Finders 等对 EUV 照明与 M3D</footer></div><p><a href="/litho/pupil-fill-ratio">上一课</a>给出填充比预算。缺口是预算内部怎么切：环形、偶极、四极，还是可编程自由光瞳。氢等离子体怎样打在这些照射足迹下的镜面上，留给<a href="/litho/hydrogen-plasma-mirrors">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PFR 只规定面积分数。同样 20% 填充，做成小 σ 常规照明与做成对向偶极，TCC 完全不同。EUV 关键层（切金属、通孔、SADP 心轴）依赖离轴极子抬 NILS；但离轴加大掩模侧角谱，<a href="/litho/euv-oblique-shadow">阴影</a> 和最佳焦点漂移加重。多层在大入射角掉 \\(R\\)、分偏振，极子太靠光瞳边缘会自我打折扣。</p><p>缺口是 EUV 特有的设置约束，不是重讲阿贝成像。DUV 浸没有水的偏振管理和巨大光子库；EUV 每换一张激进光瞳，都在问 PFR、pellicle 热指纹和 M3D 是否还收得住。</p><p><span class="marginnote">FlexPupil 一类可编程反射照明是公开方向：用镜阵列或等效元件拼光瞳。具体镜数和算法以 ASML 公开为准，不要把 DUV 衍射光学元件 DOE 直接写成 EUV 硬件。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SMO：在源与掩模上联合优化，目标函数含 NILS、PV-band、M3D 和工艺窗口。EUV 必须把 CRA 沿弧变化、flare 核、pellicle 双程放进循环，否则得到的极子在狭缝两端不可用。设置库按层别冻结：逻辑金属与孔不是同一张瞳。换源功率或收集镜老化后，要再资格认证填充形状，不能只改剂量。</p><p>常规照明仍用于较松的层，节省 SMO 与掩模复杂度。环形照明给各向同性层。偶极给一维密集线，但会牺牲另一方向，切层往往伴随定向设计规则。</p><h3 id="设置库要带狭缝坐标" tabindex="-1">设置库要带狭缝坐标 <a class="header-anchor" href="#设置库要带狭缝坐标" aria-label="Permalink to &quot;设置库要带狭缝坐标&quot;">​</a></h3><p>弧上 CRA 变化，同一张「偶极」在狭缝两端不是同一入射。把中心点 SMO 的瞳贴到全弧，边缘 NILS 和阴影会先坏。量产设置要么沿弧分段、要么在优化时就对弧采样。换收集镜或换功率后，有效源变，库要再资格认证，不能只改剂量偏移。</p>',12)),(e(),s(d,null,{default:i(()=>[p(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PFR%5B%22PFR%20%E9%A2%84%E7%AE%97%22%5D%20--%3E%20SET%5B%22%E7%8E%AF%20%2F%20%E6%9E%81%E5%AD%90%20%2F%20%E8%87%AA%E7%94%B1%E7%9E%B3%22%5D%0A%20%20SET%20--%3E%20TCC%5B%22%E9%83%A8%E5%88%86%E7%9B%B8%E5%B9%B2%E4%BC%A0%E9%80%92%22%5D%0A%20%20M3D%5B%22%E6%8E%A9%E6%A8%A1%203D%20%2F%20CRA%22%5D%20--%3E%20SET%0A%20%20PHOT%5B%22%E5%85%89%E5%AD%90%E4%B8%8E%E5%A4%9A%E5%B1%82%E8%A7%92%22%5D%20--%3E%20SET%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光瞳上每一点对应掩模上一个入射方向。极子把能量堆在对对比最有利的衍射级对上，同时把吸收体阴影推到特定方位——HV 偏置成为设置的函数。自由光瞳可以逼近 SMO 的连续解，但制造与计量变成「这张瞳今天还是不是昨天那张」。热：照明镜和掩模上的足迹随设置变，pellicle 皱纹图也变，CD 指纹跟功率爬坡耦合。</p><p><span class="marginnote">设置改的是相干结构，不是波长。随机效应要的剂量绝对值，SMO 给不了更多光子；NILS 提高可以降低对剂量的部分需求，但不能取消泊松。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写氢等离子体对帽层的溅射化学，下一课才把「照射足迹」接到氢与镜面。不把某代 NXE 的 σ 表当附录。设置一旦冻结，收集镜老化仍会改填充形状，要进再资格认证，不能当一次性 SMO 交付。出处：ASML EUV 照明 / FlexPupil；Finders、van Setten 对照明与 M3D；Bakshi 部分相干。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EUV 照明设置在 PFR 预算内切割光瞳，并受 M3D、多层角和光子约束。</li><li>SMO 必须带狭缝 CRA 与 flare，不能从浸没表复制。</li><li>下一课：这些足迹落在氢环境里的多层上会发生什么。</li><li>出处：ASML；Finders / van Setten；Bakshi。</li></ul>',7))])}const P=r(h,[["render",u]]);export{V as __pageData,P as default};
